#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    int n = strtol(argv[1], NULL, 10);
    if (n <= 0) {
        puts("BAD_INPUT");
        return 0;
    }

    long long *pascal_triangle = (long long *)calloc(n, sizeof(long long));
    pascal_triangle[0] = 1;

    for (int i = 1; i < n; i++) {
        pascal_triangle[i] = 1;
        for (int j = 1; j < i; j++) {
            pascal_triangle[j] = pascal_triangle[j] + pascal_triangle[j - 1];
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            putchar(' ');
        }
        for (int j = 0; j <= i; j++) {
            printf("%lld ", pascal_triangle[j]);
        }
        putchar('\n');
    }

    free(pascal_triangle);
    return 0;
}
